import{_ as s,O as i,o as a,c as n,a as o,i as r,f as c}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.27　审美、艺术、文学、游戏与日常文化","description":"","frontmatter":{"title":"D.27　审美、艺术、文学、游戏与日常文化","xkChars":704,"xkLessons":{"D.27":{"title":"D.27　审美、艺术、文学、游戏与日常文化","lead":"作品的形式与体验可以回答自己的问题；所有、保管、解释与社群关系又有各自的持续和改变。","explanation":["原文定位：第4951—4966行，原站定位/theory/appendix-d/d-27#section-d-27。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“作品的形式、节律、类别与观看经验可以回答自己的问题”。美、喜欢、艺术身份、用途、流行、收入、公共资助理由、社会效果不同。不能要求一幅作品先证明长期德性或群体协调才有审美意义，也不能用喜欢替代公共资助的全部理由。[T-main]","制度权力研究同样有独立作用：材料技能评价传播影响谁能创作和被看见。形式分析和生产条件分析不必互相排斥；一种分析完成自己的问题，不等另一种已自动完成或不再需要。[T-main]","文化生产的协作、惯例与控制要逐环核。评论认可不保证销售，机构清算不等作品技艺流派终止，反过来作品存世也不证明原组织仍运转。不同对象需分别判断延续。[T-main]","文学声音、聚焦、人物判断、叙述层和实际读者反应分别取证。某人物观点不能直接归作者，局部视角不自动变全知裁定；细读能支持意义解释，长期读者行为变化另需材料。[T-main]","科幻思想实验可显示条件分叉，不是宇宙社会机制的经验样本。例如《三体》作为研究入口可讨论设定如何限制选择，不能由虚构情节证成现实群体的必然行为。[T-main]","游玩过程本身可值得，认真与自由游戏可以并存。人为困难竞争角色规则不必只还原为最终收益。消费也可有实用、耐用、美感、共同经历及地位表达，多种意义可以同时存在。[T-main]","原文两器物例限定为“已指定功能”相同而形状触感带来不同体验。它说明某个功能说明未穷尽体验，不能泛化为所有功能解释无效。功能决定评分、功能足以构成美、某方面有功能美是三个不同命题。[T-main]","粉丝热爱可与维护劳动、商业控制和内部异议共存。档案在线不等原社群活跃或安全，个人仍热爱也不保证成员关系延续。日常饮食独处照护的意义不能被宏观指标耗尽，也不要求忽略实际负担。[T-main]","遗产所有、保管、研究、展陈、解释及继续改变生活的权利分开讨论。返还和经授权借展可以相容，保存街貌记忆不自动恢复原居民关系；继续改变生活也不能简单被冻结成展品式保存。[T-main]","真实参照：Smithsonian自有刊物2022年10月11日报道，其29件贝宁作品所有权转给尼日利亚，其中20件将返还、9件以借展方式留馆。所有权变化与物理留馆可以并存，留馆不单独否定返还身份。[P-SI]","该报道不是完整借展合同或后续运输记录；不能写20件当天已经抵达，不能由29件所有权转移推出所有解释权、当地生活关系或殖民伤害全面修复。案例新增观察点是不同权利和保管状态可采用不同安排。[P-SI]","正文连接§1.8—1.10、§5.10、§9.7、§10.6及附录A.3/A.11，分别保留任务、意义、经验、关系及目标/反馈边界。九入口为27.01审美经验判断；27.02生产制度产业通道；27.03叙事伦理多视角；27.04游戏仪式体育过程及Huizinga/Caillois等；27.05粉丝次文化热爱与劳动；27.06消费时尚品味多用途；27.07科幻条件思想实验；27.08日常节日饮食身体经验；27.09记忆博物馆遗产权利。名单不是已完成原作全读的声明。[T-main]"],"argumentSteps":["先明确讨论美、喜欢、用途还是社会效果。","在作品形式、生产条件与读者后果间分别取证。","核叙述视角，不把人物判断直接归作者。","按作品组织技艺社群档案各对象判断延续。","分遗产所有保管展陈解释与实际生活权利。"],"distinctions":[{"leftTitle":"功能决定评分","leftText":"评分仅由指定功能确定。","rightTitle":"某方面功能美","rightText":"功能对美有贡献，不要求穷尽评分。"},{"leftTitle":"作品细读","leftText":"解释形式意义及声音。","rightTitle":"行为因果","rightText":"要实际读者与适当证据。"},{"leftTitle":"保管在馆","leftText":"物理位置及保管安排。","rightTitle":"所有权","rightText":"权利归属可已改变。"},{"leftTitle":"档案在线","leftText":"资料仍能访问。","rightTitle":"社群延续","rightText":"成员关系活跃安全需另核。"}],"boundaries":["原文教学反例：功能相同器物仍有不同形状触感体验。","原文边界：机构清算不等作品技艺流派终止。","教学反例：两件同功能都被认为美，但评分不同，不能据评分差反驳功能足以美。"],"questions":["不同评分反驳所有功能美吗？","借展留馆证明未返还所有权吗？","文学解释完成等于德性改善证明吗？","档案在线说明社群安全活跃吗？"],"diagramPath":"/reading-assets/S-D-27/figures/d27-tasks.png","caseLinks":[{"title":"2022年Smithsonian贝宁作品所有权转移与借展","href":"https://www.smithsonianmag.com/smithsonian-institution/benin-bronzes-going-back-to-nigeria-180980917/"}],"caseNotes":[{"title":"2022年Smithsonian贝宁作品所有权转移与借展","text":"2022-10-11机构自有刊物报告29件所有权转给尼日利亚，20件将返还，9件借展留馆。","sourceLabel":"Smithsonian Magazine: The Smithsonian Returns a Trove of Benin Bronzes to Nigeria","sourceUrl":"https://www.smithsonianmag.com/smithsonian-institution/benin-bronzes-going-back-to-nigeria-180980917/","sourceLocator":"2022-10-11，首图说明及正文第二段（网页9—12行）","boundary":"计划不写成当日到达；不据此推全部解释权、损害或关系已恢复。","href":"https://www.smithsonianmag.com/smithsonian-institution/benin-bronzes-going-back-to-nigeria-180980917/"}],"sourceRefs":[{"section":"D.27","start_line":4951,"end_line":4966,"startLine":4951,"endLine":4966}],"outputId":"section-d-27","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：三个功能命题","text":"人工器物甲乙指定盛水功能F都为1，体验评分分别6和9，定义评分≥5为该例的“美”。不同评分反驳“评分只由F决定”；但两件都美，与“F足以美”在这两对象上相容，也不排除功能对部分美感的贡献。","assumptions":"虚构评分和阈值，非普遍美学定义；只给两个样本。","boundary":"没有证明充分条件普遍成立，只说明此反例不能单独反驳它。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：功能相同器物仍有不同形状触感体验。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：机构清算不等作品技艺流派终止。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：两件同功能都被认为美，但评分不同，不能据评分差反驳功能足以美。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"不同评分反驳所有功能美吗？","answer":"不能，只限制被检验的强命题。","basis":"逻辑范围。"},{"question":"借展留馆证明未返还所有权吗？","answer":"不能，所有和保管可分。","basis":"历史参照。"},{"question":"文学解释完成等于德性改善证明吗？","answer":"不等，读者行为是另一任务。","basis":"证据层。"},{"question":"档案在线说明社群安全活跃吗？","answer":"不说明，需成员关系和环境材料。","basis":"延续对象。"}],"figures":[{"path":"/reading-assets/S-D-27/figures/d27-tasks.png","alt":"形式体验、制度生产、行为效果各自有任务。","caption":"据D.27。"},{"path":"/reading-assets/S-D-27/figures/d27-function.png","alt":"人工F相同评分6/9而都过5，限制特定强命题。","caption":"教学构造。"},{"path":"/reading-assets/S-D-27/figures/d27-rights.png","alt":"2022年29件所有权转移，20拟返还9借展留馆。","caption":"机构报告指定日期，不宣称后续运输。"}],"diagramBrief":"三图分艺术任务、功能命题与返还借展。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未核完整借展合同及后续运输记录。","未对真实作品作审美评分或长期行为效果检验。"],"taskId":"S-D-27","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.27，第4951—4966行","claim_support":["审美任务、功能命题、叙事层、遗产权利延续与九入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-SI","title":"Smithsonian Magazine: The Smithsonian Returns a Trove of Benin Bronzes to Nigeria","url":"https://www.smithsonianmag.com/smithsonian-institution/benin-bronzes-going-back-to-nigeria-180980917/","source_type":"primary","version_or_date":"2022-10-11","locator":"2022-10-11，首图说明及正文第二段（网页9—12行）","claim_support":["Smithsonian的29件作品所有权转给尼日利亚，20件将返还、9件以借展方式留馆。"],"limits":["本人直接读机构自有刊物报告正文；不是完整合同核查，不能将将来返还计划写成20件已在当天到达，也不推全部解释权或生活关系已恢复。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-27/lecture.md","sourcesPath":"/reading-assets/S-D-27/sources.json","sourceSlicePath":"/reading-assets/S-D-27/source/S-D-27.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-27/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-27.md","filePath":"theory/appendix-d/d-27.md"}'),d={name:"theory/appendix-d/d-27.md"};function l(p,e,u,m,g,h){const t=i("SectionLesson");return a(),n("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-27" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.27</span><span class="xk-num__gap">　</span></span>审美、艺术、文学、游戏与日常文化 <a class="header-anchor" href="#section-d-27" aria-label="Permalink to &quot;D.27　审美、艺术、文学、游戏与日常文化 {#section-d-27}&quot;">​</a></h1><p>正文连接：§1.8—1.10；§5.10；§9.7；§10.6；附录A.3、A.11。研究入口：27.01—27.09。</p><p>美、喜欢、艺术身份、用途、流行、收入、公共资助理由和社会效果不同。作品的形式、节律、类别与观看经验可以回答自己的问题，不必先证明群体协调或长期德性改善。制度与权力研究同样有独立作用：材料、技能、评价与传播渠道会影响什么能够被创作和看见。</p><p>文化生产中的协作、惯例和控制需逐环分析。评论认同不保证销售，组织清算也不等作品、技艺与流派终止。文学的声音、聚焦、人物判断和实际读者反应分开；故事中的一种看法不自动是作者或全知叙述的裁定。科幻思想实验可展示条件分叉，不作为宇宙社会机制的经验证据。</p><p>游玩可以因过程而值得，认真和自由游戏可以并存。人为设置困难、竞争和角色规则，不必还原为最终收益；消费也可能涉及实用、耐用、美感、共同经历或地位表达。教学例：两件功能相同的器物因形状和触感带来不同体验，这说明已指定功能不足以穷尽审美，不证明所有功能解释无效。</p><p>粉丝热爱可以与维护劳动、商业控制和内部异议并存；档案仍在线不等原社群仍活跃或安全。日常饮食、独处和照护的意义不能由宏观指标耗尽。遗产的所有、保管、研究、展陈、解释与继续改变生活的权利分别讨论；返还与经授权借展可以相容，保存街貌或记忆也不自动恢复原居民的关系。</p><p>功能决定评分、功能是美的充分条件，以及某一方面具有功能美，是不同命题。同功能而体验评分不同，能够限制第一项，却不单独反驳后两项。作品细读和意义理解可以在自身任务中完成，长期行为改变则需读者材料。档案保存、个人热爱、成员关系与环境安全，也可以具有各自不同的持续与终止。</p><p>专题定位：27.01 审美经验、美与判断；27.02 艺术生产、制度与文化产业；27.03 文学、叙事伦理与多视角理解；27.04 游戏、仪式、体育与游玩：Huizinga、Caillois 等；27.05 粉丝社群、次文化与共同热爱；27.06 消费、时尚、品味与身份；27.07 思想实验与科幻：如《三体》；27.08 日常生活、节日、饮食与身体实践；27.09 历史记忆、博物馆与文化遗产。</p></div>',1)),r(t,{section:"D.27"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const T=s(d,[["render",l]]);export{f as __pageData,T as default};
